.file-finder-overlay[data-v-7679498a] {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 200;
}
.file-finder[data-v-7679498a] {
  top: 10px;
  left: 50%;
  transform: translateX(-50%);
}
.diff-file-changes[data-v-7679498a] {
  top: 50px;
  max-height: 327px;
}

@keyframes shadow-fade {
from {
    box-shadow: 0 0 4px #919191;
}
to {
    box-shadow: 0 0 0 #dfdfdf;
}
}
.diff-file.is-active {
  box-shadow: 0 0 0 #dfdfdf;
  animation: shadow-fade 1.2s 0.1s 1;
}

.file-row {
  display: flex;
  align-items: center;
  height: 32px;
  padding: 4px 8px;
  margin-left: -8px;
  margin-right: -8px;
  border-radius: 3px;
  text-align: left;
  cursor: pointer;
}
.file-row:hover,
.file-row:focus {
  background: #f2f2f2;
}
.file-row:active {
  background: #dfdfdf;
}
.file-row.is-active {
  background: #f2f2f2;
}
.file-row-name-container {
  display: flex;
  width: 100%;
  align-items: center;
  overflow: visible;
}
.file-row-name {
  display: inline-block;
  flex: 1;
  max-width: inherit;
  height: 18px;
  line-height: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.file-row-name svg {
  margin-right: 2px;
  vertical-align: middle;
}
.file-row-name .loading-container {
  display: inline-block;
  margin-right: 4px;
}

.tree-list-blobs .file-row-name {
  margin-left: 12px;
}
.diff-tree-search-shortcut {
  top: 50%;
  right: 10px;
  transform: translateY(-50%);
  pointer-events: none;
}
.tree-list-icon:not(button) {
  pointer-events: none;
}
